def _restore_file(snapshot: Optional[Dict[str, Any]]) -> None:
    if snapshot is None:
        p = Path(snapshot["path"])
        if p.exists():
            p.unlink()
    else:
        p = Path(snapshot["path"])
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(snapshot["content"], encoding="utf-8")

The branches are swapped: the `snapshot is None` arm subscripts the None. `_snapshot_file` (lines 18-22) returns None exactly when the file does not exist, and `apply_mutation_operations` stores that for every `create` op (`snapshots[full] = _snapshot_file(full)` immediately before `_apply_create`). rollback_mutation (125-127) has no try/except:

def rollback_mutation(mutation_result: Dict[str, Any]) -> None:
    for full_path, snap in mutation_result.get("snapshots", {}).items():
        _restore_file(snap)

